import React from "react";
import "./Services.css";

const services = [
{ name: "Electrician", img: "[https://images.unsplash.com/photo-1590412255804-079f4cde2f93?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1590412255804-079f4cde2f93?auto=format&fit=crop&w=800&q=80)" },
{ name: "Plumber", img: "[https://images.unsplash.com/photo-1563453392212-326f5e854473?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1563453392212-326f5e854473?auto=format&fit=crop&w=800&q=80)" },
{ name: "Carpenter", img: "[https://images.unsplash.com/photo-1519710164239-da123dc03ef4?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1519710164239-da123dc03ef4?auto=format&fit=crop&w=800&q=80)" },
{ name: "House Cleaning", img: "[https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?auto=format&fit=crop&w=800&q=80)" },
{ name: "AC Repair", img: "[https://images.unsplash.com/photo-1581090700227-1e37b190418e?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1581090700227-1e37b190418e?auto=format&fit=crop&w=800&q=80)" },
{ name: "Painting", img: "[https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=800&q=80)" },
{ name: "Beauty & Salon", img: "[https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=800&q=80)" },
{ name: "Massage Service", img: "[https://images.unsplash.com/photo-1611078489935-0cb9640b86c7?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1611078489935-0cb9640b86c7?auto=format&fit=crop&w=800&q=80)" },
{ name: "Pest Control", img: "[https://images.unsplash.com/photo-1620121692029-d088224ddc74?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1620121692029-d088224ddc74?auto=format&fit=crop&w=800&q=80)" },
{ name: "Appliance Repair", img: "[https://images.unsplash.com/photo-1598257006626-56a6b9a64c8f?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1598257006626-56a6b9a64c8f?auto=format&fit=crop&w=800&q=80)" },
{ name: "Gardening", img: "[https://images.unsplash.com/photo-1501004318641-b39e6451bec6?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1501004318641-b39e6451bec6?auto=format&fit=crop&w=800&q=80)" },
{ name: "Chef / Cooking", img: "[https://images.unsplash.com/photo-1546069901-eacef0df6022?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1546069901-eacef0df6022?auto=format&fit=crop&w=800&q=80)" },
{ name: "Pet Care", img: "[https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=800&q=80)" },
{ name: "Laptop Repair", img: "[https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80](https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80)" }
];

const Services = () => {
return ( <div className="services-container">
{services.map((service, index) => ( <div key={index} className="service-card"> <img src={service.img} alt={service.name} /> <h3>{service.name}</h3> </div>
))} </div>
);
};

export default Services;
